/**
 * The records that {@link TestBase.reset} writes into the test base.
 */

import { type ValuesForWrite } from "../records/converters.ts";
import { type BaseSchema } from "../bases/types.ts";
// @ts-ignore - This file is generated by running 'pnpm run ensure-test-base'
import testBaseSchema from "./test-base-schema.generated.ts";

type RecordWrite<B extends BaseSchema, N extends B["tables"][number]["name"]> =
    ValuesForWrite<Extract<B["tables"][number], { name: N }>["fields"][number]>;

