/**
 * Records for the allTypes table.
 *
 * Record `i` takes the `i`th value of each field's list, and leaves the field
 * empty where that value is undefined or the list is shorter.
 * AutoNumber, Count, CreatedBy, CreatedTime, Formula, LastModifiedBy,
 * LastModifiedTime, Lookup, and Rollup are computed by Airtable and not written.
 */
export function getAllTypesSeedData(linkedItemRecordIds: string[]): Record<string, unknown>[] {
    const valuesByField: Record<string, unknown[]> = {
        barcode: [
            undefined,
            { text: "123456789", type: "code128" },
            { text: "987654321", type: "code39" },
            { text: "555666777", type: "ean13" },
        ],
        checkbox: [undefined, true, false, true, false],
        currency: [undefined, 0, 99.99, 1234.56, -50.00],
        date: [undefined, "2025-01-02", "2025-12-31", "2024-06-15"],
        dateTime: [undefined, "2025-01-02T10:00:00.000Z", "2025-06-15T14:30:00.000Z", "2024-12-25T00:00:00.000Z"],
        duration: [undefined, 0, 3600, 7200, 1800], // seconds
        email: [undefined, "test@example.com", "user@domain.co.uk", "admin@site.org"],
        multilineText: [undefined, "", "Line 1\nLine 2\nLine 3", "Multi\nline\ntext", "Short"],
        multipleAttachments: [
            undefined,
            [],
            [{ url: "https://picsum.photos/200/300" }],
            [
                { url: "https://picsum.photos/400/400" },
                { url: "https://picsum.photos/300/200" },
            ],
        ],
        // multipleCollaborators: [undefined, [], []],
        // multipleRecordLinks: [
        //     undefined,
        //     [],
        //     [linkedItemRecordIds[0]],
        //     [linkedItemRecordIds[0], linkedItemRecordIds[1]],
        //     [linkedItemRecordIds[2]],
        //     [linkedItemRecordIds[1], linkedItemRecordIds[2], linkedItemRecordIds[3]],
        // ],
        multipleSelects: [undefined, [], ["Tag 1"], ["Tag 1", "Tag 2"], ["Tag 2", "Tag 3"]],
        _number: [undefined, 0, 42, -17, 3.14159, 1000000],
        percent: [undefined, 0, 0.5, 1.0, 0.25, 0.75],
        phoneNumber: [undefined, "(555) 111-2222", "+1-555-333-4444", "555.555.5555"],
        rating: [undefined, 1, 5, 10, 3, 7],
        richText: [undefined, "", "**Bold** and *italic*", "Rich text content", "Simple"],
        singleCollaborator: [undefined, undefined, undefined],
        singleLineText: [undefined, "", "Hello World", "Special !@#$ chars", "Very long text that tests the limits of single line text fields with lots of content"],
        singleSelect: [undefined, "Option A", "Option B", "Option C"],
        url: [undefined, "https://example.com", "http://test.org/path", "https://domain.com/page?q=1"],
    };

    const nRecords = Math.max(...Object.values(valuesByField).map((values) => values.length));
    return Array.from({ length: nRecords }, (_, i) => {
        const record: Record<string, unknown> = {};
        for (const [field, values] of Object.entries(valuesByField)) {
            if (values[i] !== undefined && values[i] !== null) {
                record[field] = values[i];
            }
        }
        return record;
    });
}
